UPDATE products SET details = details || '{"evidence":[{"title":"PFAS 혼합물·미세플라스틱 시험","summary":"공식 성능표는 지정된 7종 PFAS 혼합물의 저감률을 99.75%, 미세플라스틱 저감률을 99.8%로 제시합니다. 호환 모델과 표준 시험 조건에 한정됩니다.","source":"https://www.pur.com/wp-content/uploads/PUR_PDS_Pitcher_Filters_PPF951K.pdf","topic":"pfas-filter"},{"title":"브랜드와 미국 유통 법인","summary":"상장사 Helen of Troy는 PUR를 주요 브랜드로 공개합니다. 미국 제품 성능표에는 자회사 Kaz USA가 유통 주체로 기재됩니다.","source":"https://www.helenoftroy.com/our-brands/"}]}'::jsonb WHERE id = 'pur-plus-ppf951k';
UPDATE products SET details = details || '{"evidence":[{"title":"저감 성능 시험 조건","summary":"제조사가 PFOA·PFOS 저감과 IAPMO의 지정 표준 인증을 공개합니다. 성능표에 표시된 시험 조건과 항목별 결과를 확인할 수 있습니다.","source":"https://www.aosmithatlowes.com/media/1234/ao-us-ro-mb-4000_pds.pdf","topic":"pfas-filter"},{"title":"미국 EPA의 정수 필터 인증 안내","summary":"EPA는 해당 물질의 저감 인증과 제품별 성능표를 확인하도록 안내합니다.","source":"https://www.epa.gov/water-research/identifying-drinking-water-filters-certified-reduce-pfas"}]}'::jsonb WHERE id = 'ao-smith-ro-mb4000';
